"""flights-search: GET /flights/search

Scan the flight table with an exact-equality filter on the three schedule
fields and return the first page of matches (SI-12: no LastEvaluatedKey
handling, no pagination). A failed Scan is swallowed and answers an empty
list (SI-13). Values read back from DynamoDB keep the monolith's
Decimal -> int/float shape (SI-16). Every response carries the app-wide
headers (SI-14).
"""
import json
import os
from decimal import Decimal

import boto3
from boto3.dynamodb.conditions import Attr

FLIGHT_TABLE_NAME = os.environ["FLIGHT_TABLE_NAME"]

_dynamodb = boto3.resource("dynamodb")
flight_table = _dynamodb.Table(FLIGHT_TABLE_NAME)


def json_response(status_code, payload):
    """Single place where the app-wide response headers are set (SI-14)."""
    return {
        "statusCode": status_code,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "*",
        },
        "body": json.dumps(payload),
    }


def to_dynamodb(value):
    """float -> Decimal(str(v)), as the monolith writes it (SI-16)."""
    if isinstance(value, float):
        return Decimal(str(value))
    if isinstance(value, dict):
        return {k: to_dynamodb(v) for k, v in value.items()}
    if isinstance(value, list):
        return [to_dynamodb(v) for v in value]
    return value


def from_dynamodb(value):
    """Decimal -> int when whole, float otherwise (SI-16)."""
    if isinstance(value, Decimal):
        if value % 1 == 0:
            return int(value)
        return float(value)
    if isinstance(value, dict):
        return {k: from_dynamodb(v) for k, v in value.items()}
    if isinstance(value, list):
        return [from_dynamodb(v) for v in value]
    return value


def search_flights(departure_code, arrival_code, departure_date):
    """One Scan, first page only; a storage failure reads as an empty list."""
    try:
        response = flight_table.scan(
            FilterExpression=Attr("departureAirportCode").eq(departure_code)
            & Attr("arrivalAirportCode").eq(arrival_code)
            & Attr("departureDate").eq(departure_date)
        )
        return [from_dynamodb(item) for item in response.get("Items", [])]
    except Exception as exc:  # noqa: BLE001 - the monolith swallows it
        print(f"Error searching flights: {str(exc)}")
        return []


def lambda_handler(event, context):
    query = event.get("queryStringParameters") or {}
    departure_code = query.get("departureCode")
    arrival_code = query.get("arrivalCode")
    departure_date = query.get("departureDate")

    if not all([departure_code, arrival_code, departure_date]):
        return json_response(400, {"error": "Missing required parameters"})

    flights = search_flights(departure_code, arrival_code, departure_date)
    return json_response(200, {"flights": flights})

"""bookings-cancel: POST /bookings/{booking_id}/cancel

Existence + owner/admin check first, with the same 404/403 texts as
bookings-get; when authorization fails the booking is not touched, no seat
is released and nothing is refunded (business_rules[0]). The booking is
read once and that one item serves authorization and the two compensation
steps (SI-1).

Then three best-effort steps, serial and not a transaction (SI-18):
  1. status 'CANCELLED' - bookingReference is left as it was and checkedIn
     is not changed (business_rules[1]);
  2. release one seat on the flight stored in the booking's own
     bookingOutboundFlightId (not from the request body); a failure is only
     logged and the response stays 200 (business_rules[2]/[3]);
  3. refund the payment stored in the booking's own paymentToken; a failure
     replaces the refund object with {'refundId': 'N/A', 'status': 'failed'}
     and the response still stays 200 (business_rules[4]).
No state check: cancelling an already CANCELLED booking returns 200 again,
refunds once more and releases one more seat until the cap makes that
failure get swallowed (business_rules[5], SI-17). The notification is the
locally assembled dict with status 'cancelled', price 0 and
'most recent booking' in the subject (SI-5). An unauthenticated call is
answered 401 by the gateway (SI-9). Every response carries the app-wide
headers (SI-14).
"""
import json
import os
import secrets
from decimal import Decimal

import boto3

BOOKING_TABLE_NAME = os.environ["BOOKING_TABLE_NAME"]
FLIGHT_TABLE_NAME = os.environ["FLIGHT_TABLE_NAME"]
PAYMENT_TABLE_NAME = os.environ["PAYMENT_TABLE_NAME"]
USER_GROUPS_TABLE_NAME = os.environ["USER_GROUPS_TABLE_NAME"]

_dynamodb = boto3.resource("dynamodb")
booking_table = _dynamodb.Table(BOOKING_TABLE_NAME)
flight_table = _dynamodb.Table(FLIGHT_TABLE_NAME)
payment_table = _dynamodb.Table(PAYMENT_TABLE_NAME)
user_groups_table = _dynamodb.Table(USER_GROUPS_TABLE_NAME)
CONDITIONAL_CHECK_FAILED = _dynamodb.meta.client.exceptions.ConditionalCheckFailedException


def json_response(status_code, payload):
    """Single place where the app-wide response headers are set (SI-14)."""
    return {
        "statusCode": status_code,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "*",
        },
        "body": json.dumps(payload),
    }


def from_dynamodb(value):
    """Decimal -> int when whole, float otherwise (SI-16)."""
    if isinstance(value, Decimal):
        if value % 1 == 0:
            return int(value)
        return float(value)
    if isinstance(value, dict):
        return {k: from_dynamodb(v) for k, v in value.items()}
    if isinstance(value, list):
        return [from_dynamodb(v) for v in value]
    return value


def claims_of(event):
    """Identity comes from the gateway-verified claims only (SI-10)."""
    return (event.get("requestContext") or {}).get("authorizer", {}).get("claims") or {}


def is_admin(sub):
    """Admin comes from UserGroupsTable.groups; no row or a failed read is no
    groups, never a 401 (SI-10)."""
    try:
        response = user_groups_table.get_item(Key={"sub": sub})
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting user groups {sub}: {str(exc)}")
        return False
    item = response.get("Item") or {}
    groups = item.get("groups") or []
    return "Admin" in list(groups)


def get_booking(booking_id):
    """One read by primary key; a failed read reads as 'not there' (SI-13)."""
    try:
        response = booking_table.get_item(Key={"id": booking_id})
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting booking {booking_id}: {str(exc)}")
        return None
    if "Item" in response:
        return from_dynamodb(response["Item"])
    return None


def get_flight(flight_id):
    try:
        response = flight_table.get_item(Key={"id": flight_id})
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting flight {flight_id}: {str(exc)}")
        return None
    if "Item" in response:
        return from_dynamodb(response["Item"])
    return None


def release_flight_seat(flight_id):
    """Same conditional increment as flights-release, capped by the flight's
    own maximumSeating."""
    try:
        flight = get_flight(flight_id)
        if not flight:
            raise ValueError(f"Flight {flight_id} does not exist")

        flight_table.update_item(
            Key={"id": flight_id},
            UpdateExpression="SET seatCapacity = seatCapacity + :inc",
            ConditionExpression="seatCapacity < :max",
            ExpressionAttributeValues={":inc": 1, ":max": flight["maximumSeating"]},
            ReturnValues="UPDATED_NEW",
        )
        return True
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError("Cannot release seat, already at maximum capacity")
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to release seat: {str(exc)}")


def refund_payment(charge_id):
    """Simulation refund: a new refundId every call, and the stored payment
    record marked 'refunded' only when it exists."""
    if not charge_id:
        raise ValueError("Invalid Charge ID")

    try:
        hash(charge_id)
    except TypeError:
        raise TypeError(f"unhashable type: '{type(charge_id).__name__}'")

    refund_id = secrets.token_urlsafe(16)

    # A non-string chargeId has no row under this table's string key, so there
    # is nothing to mark; the refund answer stays the same (SI-6, SI-19).
    if isinstance(charge_id, str):
        try:
            payment_table.update_item(
                Key={"chargeId": charge_id},
                UpdateExpression="SET #status = :status",
                ExpressionAttributeNames={"#status": "status"},
                ExpressionAttributeValues={":status": "refunded"},
                ConditionExpression="attribute_exists(chargeId)",
            )
        except CONDITIONAL_CHECK_FAILED:
            pass

    return {"refundId": refund_id}


def notify_booking(customer_id, price, booking_reference=None):
    """Locally assembled notification, never stored or sent (SI-5)."""
    booking_status = "confirmed" if booking_reference else "cancelled"
    reference_text = booking_reference or "most recent booking"

    return {
        "notificationId": secrets.token_urlsafe(16),
        "customerId": customer_id,
        "price": price,
        "status": booking_status,
        "subject": f"Booking {booking_status} for {reference_text}",
    }


def lambda_handler(event, context):
    try:
        booking_id = (event.get("pathParameters") or {}).get("booking_id")

        booking = get_booking(booking_id)
        if not booking:
            return json_response(404, {"error": "Booking not found"})

        sub = claims_of(event).get("sub")
        if sub != booking["customer"] and not is_admin(sub):
            return json_response(403, {"error": "Access denied. You can only access your own bookings."})

        # 1. Cancel the booking. The conditional write is the existence check
        #    (SI-1: no second or third read of this key in one request).
        try:
            booking_table.update_item(
                Key={"id": booking_id},
                UpdateExpression="SET #status = :status",
                ExpressionAttributeNames={"#status": "status"},
                ExpressionAttributeValues={":status": "CANCELLED"},
                ConditionExpression="attribute_exists(id)",
                ReturnValues="ALL_NEW",
            )
        except CONDITIONAL_CHECK_FAILED:
            raise ValueError(f"Booking {booking_id} not found")
        except Exception as exc:  # noqa: BLE001
            raise ValueError(f"Failed to update booking: {str(exc)}")

        # 2. Release the seat the booking stored - failure is only logged.
        try:
            release_flight_seat(booking["bookingOutboundFlightId"])
        except Exception as exc:  # noqa: BLE001
            print(f"Warning: Failed to release flight seat: {str(exc)}")

        # 3. Refund the payment token the booking stored - a failure is
        #    reported inside the 200 body, nothing else.
        try:
            refund_result = refund_payment(booking["paymentToken"])
        except Exception as exc:  # noqa: BLE001
            print(f"Warning: Failed to refund payment: {str(exc)}")
            refund_result = {"refundId": "N/A", "status": "failed"}

        notification = notify_booking(booking["customer"], 0, None)

        return json_response(200, {
            "bookingId": booking_id,
            "status": "CANCELLED",
            "refund": refund_result,
            "notification": notification,
        })
    except ValueError as exc:
        return json_response(400, {"error": str(exc), "type": "ValueError"})
    except Exception as exc:  # noqa: BLE001 - same mapping as the monolith
        return json_response(500, {"error": str(exc), "type": type(exc).__name__})

"""loyalty-get: GET /loyalty/{customer_id}

Authorization first (owner of the path id, or Admin per UserGroupsTable);
nothing is read from the loyalty table when it fails. The total is the sum
over one page of a Scan filtered on customerId + flag='active', so a
storage failure counts as 0 and the tier maths below still answers 200
(SI-12, SI-13). Tier thresholds and the remaining-points maths are the
monolith's constants. Every response carries the app-wide headers (SI-14).
"""
import json
import os
from decimal import Decimal

import boto3
from boto3.dynamodb.conditions import Attr

LOYALTY_TABLE_NAME = os.environ["LOYALTY_TABLE_NAME"]
USER_GROUPS_TABLE_NAME = os.environ["USER_GROUPS_TABLE_NAME"]

_dynamodb = boto3.resource("dynamodb")
loyalty_table = _dynamodb.Table(LOYALTY_TABLE_NAME)
user_groups_table = _dynamodb.Table(USER_GROUPS_TABLE_NAME)

TIER_GOLD = 100000
TIER_SILVER = 50000


def json_response(status_code, payload):
    """Single place where the app-wide response headers are set (SI-14)."""
    return {
        "statusCode": status_code,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "*",
        },
        "body": json.dumps(payload),
    }


def claims_of(event):
    """Identity comes from the gateway-verified claims only (SI-10)."""
    return (event.get("requestContext") or {}).get("authorizer", {}).get("claims") or {}


def is_admin(sub):
    """Admin membership is read from UserGroupsTable on every request; no row
    (or a failed read) means no groups, never a 401 (SI-10)."""
    try:
        response = user_groups_table.get_item(Key={"sub": sub})
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting user groups {sub}: {str(exc)}")
        return False
    item = response.get("Item") or {}
    groups = item.get("groups") or []
    return "Admin" in list(groups)


def get_loyalty_points(customer_id):
    """Sum of the first Scan page's active points; a failure counts as 0."""
    try:
        response = loyalty_table.scan(
            FilterExpression=Attr("customerId").eq(customer_id) & Attr("flag").eq("active")
        )
        total = 0
        for item in response.get("Items", []):
            total += int(item.get("points", 0))
        return total
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting loyalty points for {customer_id}: {str(exc)}")
        return 0


def get_loyalty_level(points):
    if points >= TIER_GOLD:
        return "gold"
    if points >= TIER_SILVER:
        return "silver"
    return "bronze"


def get_remaining_points_to_next_tier(points, level):
    if level == "bronze":
        return TIER_SILVER - points
    if level == "silver":
        return TIER_GOLD - points
    return 0


def lambda_handler(event, context):
    customer_id = (event.get("pathParameters") or {}).get("customer_id")
    sub = claims_of(event).get("sub")

    if sub != customer_id and not is_admin(sub):
        return json_response(403, {"error": "Access denied. You can only access your own resources."})

    total_points = get_loyalty_points(customer_id)
    level = get_loyalty_level(total_points)
    remaining_points = get_remaining_points_to_next_tier(total_points, level)

    return json_response(200, {
        "points": total_points,
        "level": level,
        "remainingPoints": remaining_points,
    })
"""bookings-confirm: POST /bookings/{booking_id}/confirm

Existence + owner/admin check first, exactly as bookings-get (404
